// Demo: Optical Character Recognition Trainer - public implementations survey
(function(){'use strict';
var DATA={"label": "Optical Character Recognition Trainer - public implementatio", "rows": [["OpenCV", "23"], ["  OpenCV ", "44"], ["ImageNet", "67"], ["COCO", "76"], ["  COCO ", "32"], ["Albumentations", "53"], ["ResNet", "21"], ["  ResNet ", "45"], ["", ""], ["OpenCV", "42"]]};

var seen={},kept=[],droppedEmpty=0,droppedDup=0;
console.log('Cleaning '+DATA.rows.length+' rows ('+DATA.label+'):');
DATA.rows.forEach(function(r){
  var cells=r.map(function(c){return String(c).trim();});
  if(cells.every(function(c){return c==='';})){droppedEmpty++;return;}
  var key=cells.join('|').toLowerCase();
  if(seen[key]){droppedDup++;return;}
  seen[key]=1;kept.push(cells);});
kept.forEach(function(r){console.log('  '+r.join(' | '));});
console.log('kept='+kept.length+' dropped_empty='+droppedEmpty+' dropped_dup='+droppedDup);
})();

// JAH demo program - run with: node demo.js (or paste into a browser console)
// Demo: OpenCV - related Optical Character Recognition Trainer technology
(function(){'use strict';
var DATA={"label": "OpenCV - related Optical Character Recognition Trainer techn", "arr": [24, 92, 83, 44, 61, 78, 23, 64]};

var a=DATA.arr.slice(),cmp=0,sw=0;
function qs(lo,hi){if(lo>=hi)return;var piv=a[hi],i=lo;
  for(var j=lo;j<hi;j++){cmp++;if(a[j]<piv){var t=a[i];a[i]=a[j];a[j]=t;i++;sw++;}}
  var t2=a[i];a[i]=a[hi];a[hi]=t2;sw++;qs(lo,i-1);qs(i+1,hi);}
console.log('Quicksort ('+DATA.label+'): input ['+DATA.arr.join(', ')+']');
qs(0,a.length-1);
console.log('sorted: ['+a.join(', ')+']');
console.log('comparisons='+cmp+' swaps='+sw);
})();

